    ('Thai green curry with chicken', [('chicken thigh', 130), ('curry paste', 15), ('light coconut milk', 150), ('bell pepper', 50), ('green beans', 60), ('basil', 3), ('jasmine rice', 150), ('fish sauce', 5)], 'Fry the curry paste, add chicken and cook, then coconut milk and vegetables for 10 minutes; finish with basil and fish sauce.'),
    ('Chickpea spinach coconut curry', [('chickpeas', 150), ('light coconut milk', 120), ('diced tomatoes', 100), ('spinach', 50), ('onion', 40), ('brown rice', 140), ('curry powder', 6)], 'Sauté onion with curry powder, add chickpeas, tomatoes and coconut milk and simmer 15 minutes; wilt in the spinach.'),
    ('Palak paneer', [('paneer', 90), ('spinach', 200), ('onion', 40), ('tomato', 60), ('greek yogurt', 40), ('basmati rice', 120), 'Garlic, ginger, garam masala, cumin'], 'Sauté onion, garlic, ginger and spices, add spinach and tomato and cook down, blend, then add yogurt and seared paneer cubes.'),
    ('Thai red curry with shrimp', [('shrimp', 150), ('curry paste', 15), ('light coconut milk', 150), ('bell pepper', 50), ('zucchini', 60), ('jasmine rice', 150), ('lime juice', 8)], 'Fry curry paste, add coconut milk and vegetables for 6 minutes, then shrimp for 3 minutes; finish with lime.'),
    ('Japanese chicken curry', [('chicken thigh', 120), ('potato', 100), ('carrot', 60), ('onion', 50), ('white rice', 150), ('curry powder', 6), ('flour', 8), ('honey', 5), ('soy sauce', 6), ('broth', 250)], 'Brown chicken and onion, stir in flour and curry powder, add broth, potato, carrot, soy and honey, and simmer 20 minutes until thick.'),
    ('Massaman tofu curry', [('firm tofu', 160), ('potato', 100), ('light coconut milk', 150), ('onion', 40), ('peanuts', 10), ('curry paste', 15), ('jasmine rice', 120), ('lime juice', 8)], 'Fry curry paste, add coconut milk, potato and onion and simmer 15 minutes, then add seared tofu; top with peanuts and lime.'),
    ('Beef rendang-style curry', [('sirloin', 130), ('light coconut milk', 120), ('onion', 40), ('jasmine rice', 150), ('green beans', 60), 'Lemongrass, ginger, garlic, chili, cinnamon'], 'Blend onion, garlic, ginger and chili into a paste, fry it, add beef and coconut milk and simmer until thick and dry, about 30 minutes.'),
